import React, { useState } from "react";
import { useParams } from "react-router-dom"; // Make sure to import useParams

const FuelPage = () => {
  const { id } = useParams();
  const [fuelData, setFuelData] = useState([]);
  const [newFuel, setNewFuel] = useState({
    fill_date: "",
    bunk_name: "",
    total_amount: "",
    amount_paid: "",
  });
  const [loading, setLoading] = useState(false);

  // Fetch fuel data when called (on button click)
  const fetchFuelData = async () => {
    if (!id) {
      console.error("Lorry ID is missing!");
      return;
    }
    setLoading(true);
    try {
      const response = await fetch(`http://localhost:5001/api/fuel/${id}`);
      const data = await response.json();
      setFuelData(data);
    } catch (error) {
      console.error("Error fetching fuel data:", error);
    } finally {
      setLoading(false);
    }
  };

  // Input change handler
  const handleInputChange = (e) => {
    setNewFuel({ ...newFuel, [e.target.name]: e.target.value });
  };

  // Add fuel record handler
  const handleAddFuel = async (e) => {
    e.preventDefault();
    try {
      const response = await fetch("http://localhost:5001/api/fuel/add", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          lorry_id: id,
          ...newFuel,
        }),
      });
      if (response.ok) {
        alert("Fuel details added successfully!");
        setNewFuel({
          fill_date: "",
          bunk_name: "",
          total_amount: "",
          amount_paid: "",
        });
        fetchFuelData(); // Refresh data after adding
      } else {
        alert("Error adding fuel data");
      }
    } catch (error) {
      console.error("Error adding fuel data:", error);
    }
  };

  // Delete fuel record handler
  const handleDeleteFuel = async (fuelId) => {
    try {
      const response = await fetch(
        `http://localhost:5001/api/fuel/delete/${fuelId}`,
        { method: "DELETE" }
      );
      if (response.ok) {
        alert("Fuel record deleted successfully!");
        fetchFuelData(); // Refresh data after deleting
      } else {
        alert("Error deleting fuel record");
      }
    } catch (error) {
      console.error("Error deleting fuel record:", error);
    }
  };

  return (
    <div>
      <h1>Fuel Details for Lorry ID: {id}</h1>
      <button onClick={fetchFuelData}>Fetch Fuel Details</button> {/* Fetch on button click */}

      <form onSubmit={handleAddFuel}>
        <input
          type="date"
          name="fill_date"
          value={newFuel.fill_date}
          onChange={handleInputChange}
          required
        />
        <input
          type="text"
          name="bunk_name"
          placeholder="Bunk Name"
          value={newFuel.bunk_name}
          onChange={handleInputChange}
          required
        />
        <input
          type="number"
          name="total_amount"
          placeholder="Total Amount"
          value={newFuel.total_amount}
          onChange={handleInputChange}
          required
        />
        <input
          type="number"
          name="amount_paid"
          placeholder="Amount Paid"
          value={newFuel.amount_paid}
          onChange={handleInputChange}
          required
        />
        <button type="submit">Add Fuel Record</button>
      </form>

      {loading ? (
        <p>Loading fuel details...</p>
      ) : fuelData.length > 0 ? (
        <table>
          <thead>
            <tr>
              <th>Date</th>
              <th>Bunk Name</th>
              <th>Total Amount</th>
              <th>Amount Paid</th>
              <th>Remaining Amount</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {fuelData.map((fuel, index) => (
              <tr key={index}>
                <td>{fuel.fill_date}</td>
                <td>{fuel.bunk_name}</td>
                <td>{fuel.total_amount}</td>
                <td>{fuel.amount_paid}</td>
                <td>{fuel.total_amount - fuel.amount_paid}</td>
                <td>
                  <button onClick={() => handleDeleteFuel(fuel.id)}>
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>No fuel details found for this lorry.</p>
      )}
    </div>
  );
};

export default FuelPage;
